'use client'
import { useToast } from '@/hooks/useToast'
import { motion } from 'framer-motion'
import { CheckCircle, Loader2, Send } from 'lucide-react'
import Link from 'next/link'
import { useState } from 'react'

export default function Contact() {
    const [loading, setLoading] = useState(false)
    const { showSuccess, showError, showLoading, dismiss } = useToast()

    async function handleSubmit(e) {
        e.preventDefault()
        setLoading(true)

        const loadingToastId = showLoading('Sending your message...')

        const name = e.target.name.value
        const email = e.target.email.value
        const message = e.target.message.value

        // Set a timeout for the fetch request
        const controller = new AbortController()
        const timeoutId = setTimeout(() => controller.abort(), 10000) // 10 seconds

        try {
            const res = await fetch('/api/contact', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    name,
                    email,
                    message
                }),
                signal: controller.signal
            })

            clearTimeout(timeoutId)

            const data = await res.json()

            dismiss(loadingToastId) // Dismiss loading toast

            if (res.ok && data.success) {
                showSuccess('Message sent successfully! Our team will contact you within 24 hours.')
                e.target.reset()
            } else {
                showError(data.message || 'Failed to send message. Please try again.')
            }
        } catch (err) {
            clearTimeout(timeoutId)
            dismiss(loadingToastId)
            if (err.name === 'AbortError') {
                showError('Request timed out. Please try again.')
            } else {
                showError('Network error. Please check your connection and try again.')
            }
            console.error('Fetch error:', err)
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="min-h-screen bg-gradient-to-br from-gray-900 via-blue-900 to-purple-900 py-20 relative overflow-hidden">
            {/* Background Elements */}
            <div className="absolute inset-0">
                <div className="absolute top-0 right-0 w-96 h-96 bg-cyan-500/10 rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 left-0 w-96 h-96 bg-purple-500/10 rounded-full blur-3xl"></div>
            </div>

            <div className="relative z-10 container mx-auto px-6">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="text-center mb-12"
                >
                    <h1 className="text-5xl md:text-6xl font-bold mb-6 bg-gradient-to-r from-cyan-400 to-purple-400 bg-clip-text text-transparent">
                        Get Started Today
                    </h1>
                    <p className="text-xl text-gray-300 max-w-2xl mx-auto">
                        Ready to secure your business? Fill out the form below and our team will contact you within 24 hours.
                    </p>
                </motion.div>

                <div className="grid lg:grid-cols-2 gap-12 max-w-6xl mx-auto">
                    {/* Contact Form */}
                    <motion.div
                        initial={{ opacity: 0, x: -30 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.2 }}
                        className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 border border-white/20"
                    >
                        <h2 className="text-2xl font-bold text-white mb-6">Start Your Free Consultation</h2>

                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div>
                                <label className="block text-white mb-2">Full Name</label>
                                <input
                                    type="text"
                                    name="name"
                                    required
                                    className="w-full p-4 bg-black/40 border border-white/30 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-cyan-400 transition-colors"
                                    placeholder="John Doe"
                                />
                            </div>

                            <div>
                                <label className="block text-white mb-2">Business Email</label>
                                <input
                                    type="email"
                                    name="email"
                                    required
                                    className="w-full p-4 bg-black/40 border border-white/30 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-cyan-400 transition-colors"
                                    placeholder="john@company.com"
                                />
                            </div>

                            <div>
                                <label className="block text-white mb-2">Message</label>
                                <textarea
                                    rows="4"
                                    name="message"
                                    required
                                    className="w-full p-4 bg-black/40 border border-white/30 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:border-cyan-400 transition-colors"
                                    placeholder="Tell us about your security needs..."
                                ></textarea>
                            </div>

                            <button
                                type="submit"
                                disabled={loading}
                                className="w-full bg-gradient-to-r from-cyan-500 to-blue-600 py-4 rounded-lg font-semibold text-white hover:shadow-2xl hover:shadow-cyan-500/30 transition-all transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                            >
                                {loading ? (
                                    <>
                                        <Loader2 className="h-5 w-5 animate-spin" />
                                        Sending...
                                    </>
                                ) : (
                                    <>
                                        <Send className="h-5 w-5" />
                                        Request Free Consultation
                                    </>
                                )}
                            </button>

                            <p className="text-gray-400 text-sm text-center">
                                By submitting, you agree to our Privacy Policy and Terms of Service.
                            </p>
                        </form>
                    </motion.div>

                    {/* Contact Info */}
                    <motion.div
                        initial={{ opacity: 0, x: 30 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: 0.4 }}
                        className="space-y-8"
                    >
                        <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 border border-white/20">
                            <h3 className="text-2xl font-bold text-white mb-6">Prefer to Talk?</h3>
                            <div className="space-y-4 text-gray-300">
                                <p className="flex items-center gap-3">
                                    <span className="text-cyan-400">📞</span>
                                    <strong>+91-9753089649</strong>
                                </p>
                                <p className="flex items-center gap-3">
                                    <span className="text-cyan-400">✉️</span>
                                    <strong>techodite@gmail.com</strong>
                                </p>
                                <p className="flex items-center gap-3">
                                    <span className="text-cyan-400">🕒</span>
                                    <strong>24/7 Support Available</strong>
                                </p>
                            </div>
                            <div className="mt-6 flex gap-4">
                                <Link href="/services">
                                    <button className="border border-cyan-400 text-cyan-400 px-6 py-3 rounded-lg font-semibold hover:bg-cyan-400/10 transition-all">
                                        View Services
                                    </button>
                                </Link>
                                <Link href="/">
                                    <button className="border border-purple-400 text-purple-400 px-6 py-3 rounded-lg font-semibold hover:bg-purple-400/10 transition-all">
                                        Back to Home
                                    </button>
                                </Link>
                            </div>
                        </div>

                        {/* Success Tips */}
                        <div className="bg-gradient-to-r from-green-900/20 to-emerald-900/20 backdrop-blur-lg rounded-2xl p-8 border border-emerald-800/30">
                            <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
                                <CheckCircle className="h-5 w-5 text-emerald-400" />
                                What happens next?
                            </h3>
                            <ul className="space-y-3 text-gray-300">
                                <li className="flex items-start gap-2">
                                    <span className="text-emerald-400">✓</span>
                                    <span>You'll receive a confirmation email within 5 minutes</span>
                                </li>
                                <li className="flex items-start gap-2">
                                    <span className="text-emerald-400">✓</span>
                                    <span>Our security expert will review your requirements</span>
                                </li>
                                <li className="flex items-start gap-2">
                                    <span className="text-emerald-400">✓</span>
                                    <span>We'll schedule a free consultation call at your convenience</span>
                                </li>
                                <li className="flex items-start gap-2">
                                    <span className="text-emerald-400">✓</span>
                                    <span>Receive a custom proposal within 48 hours</span>
                                </li>
                            </ul>
                        </div>
                    </motion.div>
                </div>
            </div>
        </div>
    )
}
